pub(crate) fn validate_submit_admission_with_contracts(
    &self,
    run: RunId,
    workflow: &CompiledWorkflow,
    caps: CapabilitySet,
    action_contracts: &[vb_core::action::ActionContract],
) -> RuntimeResult<()> {
    // Build admission to validate workflow digest
    let digest = workflow.digest();
    self.build_admission(run, digest, caps.clone())?;

    // Validate action contracts: ID matches index, no duplicates, well-formed
    let mut seen_ids = std::collections::HashSet::new();
    for (index, contract) in action_contracts.iter().enumerate() {
        let expected_id = vb_core::ids::ActionId::new(
            u16::try_from(index).map_err(|_| RuntimeError::ContractValidationError {
                action: contract.id,
                error: "contract index exceeds ActionId range".to_string(),
            })?,
        );
        if contract.id != expected_id {
            return Err(RuntimeError::ContractValidationError {
                action: contract.id,
                error: format!(
                    "contract at index {} has ID {} (expected {})",
                    index,
                    contract.id.get(),
                    expected_id.get()
                ),
            });
        }
        if !seen_ids.insert(contract.id) {
            return Err(RuntimeError::ContractValidationError {
                action: contract.id,
                error: "duplicate action ID".to_string(),
            });
        }
        if contract.name.as_str().is_empty() {
            return Err(RuntimeError::ContractValidationError {
                action: contract.id,
                error: "action name is empty".to_string(),
            });
        }
    }

    // Validate that granted capabilities cover all contract requirements
    for contract in action_contracts {
        for required in contract.required_capabilities.iter() {
            if !caps.grants(required) {
                return Err(RuntimeError::AdmissionCapabilityDenied {
                    action: contract.id,
                    required: required.clone(),
                    granted: caps,
                });
            }
        }
    }

    // Validate each workflow Do action has a contract at its registry index
    let mut index = 0u16;
    let count = workflow.node_count();
    while index < count {
        let step = StepIdx::new(index);
        if let Some(node) = workflow.node(step) {
            if let vb_core::workflow::CompiledNodeKind::Do { action, .. } = node.kind {
                let action_index = usize::from(action.get());
                if action_index >= action_contracts.len() {
                    return Err(RuntimeError::ContractValidationError {
                        action,
                        error: "no contract for workflow Do action".to_string(),
                    });
                }
                let contract = &action_contracts[action_index];
                if contract.id != action {
                    return Err(RuntimeError::ContractValidationError {
                        action,
                        error: "contract ID mismatch for workflow Do action".to_string(),
                    });
                }
            }
        }
        index = index.saturating_add(1);
    }

    Ok(())
}
pub fn handle_resume(&mut self, run: RunId) -> Result<ResumeResult, ResumeError> {

    self.validate_run_exists(run)?;
    let current_state = self.get_runtime_state_or_running(run);
    if current_state == RuntimeState::Running {
        return Ok(ResumeResult {
            run_id: run,
            status: ResumeStatus::AlreadyRunning,
            timestamp: current_timestamp(),
        });
    }
    if current_state != RuntimeState::Resumable {
        return Err(ResumeError::NotResumable {
            run_id: run,
            current_state,
        });
    }
    let timestamp = self.append_resumed_event(run)?;
    let drive_result = self.drive_run(run);
    self.observe_resume_drive_result(run, drive_result)?;
    Ok(ResumeResult {
        run_id: run,
        status: ResumeStatus::Resumed,
        timestamp,
    })
}

/// Recovers a run from a pre-hydrated `RunFrame` by loading the
/// compiled workflow from the artifact store and constructing a full
/// `RunState`.
///
/// The workflow digest comes from the journal recovery summary and is
/// used to look up the `AcceptedArtifact` whose `ir` field contains the
/// postcard-encoded `WorkflowParts`. The parts are deserialized and
/// validated via `CompiledWorkflow::try_from_parts`.
///
/// Recovery differs from submit in three ways:
/// - No `prepare_run_slots` / `take_frame_for` — the frame is pre-hydrated.
/// - The artifact store is queried by digest rather than the workflow being
///   passed directly.
/// - Admission is built with empty capabilities (caps are not persisted
///   per-run in the journal; runs requiring non-empty caps will fail
///   admission during recovery, which is the correct fail-closed behavior).
/// Recovers a run from full recovery context provided by journal replay.
///
/// The typed `RecoverRunCommand` carries all recovery evidence: artifact
/// digest for verification, workflow digest for identity validation,
/// journal sequence for sequencing, collect states for pagination
/// resumption, and boundary classification for suspended operations.
///
/// Recovery flow:
/// 1. Load artifact by artifact_digest (verification)
/// 2. Deserialize and compile workflow from artifact IR

// vb-3l40a: Admission contract validation tests with real Do workflows.
// Validates action contract IDs against actual workflow Do actions.
// Uses imports from chunk_001.rs via shared module scope.

fn contract_validation_test_shard() -> Shard {
    let config = ShardConfig {
        command_queue_capacity: 64,
        trace_capacity: 64,
        step_budget_per_tick: 4,
        max_active_runs: 8,
        policy: vb_core::policy::RuntimePolicy::Relaxed,
    };
    Shard::new(config)
}

fn contract_validation_do_workflow(action_id: u16) -> CompiledWorkflow {
    let node = CompiledNode {
        id: StepIdx::ZERO,
        output: Some(SlotIdx::ZERO),
        next: None,
        on_error: None,
        error_slot: None,
        kind: CompiledNodeKind::Do {
            action: ActionId::new(action_id),
            input: SlotIdx::ZERO,
        },
    };
    let parts = WorkflowParts {
        name: Box::from("test-do-workflow"),
        digest: WorkflowDigest::from_bytes([1; 32]),
        nodes: Box::from([node]),
        expressions: Box::from([]),
        accessors: Box::from([]),
        constants: Box::from([]),
        slot_count: 1,
        symbols_count: 0,
        entry: StepIdx::ZERO,
        step_names: Box::from([]),
        resource_contract: ResourceContract::DEFAULT,
        input_slots: Box::from([]),
    };
    CompiledWorkflow::try_from_parts(parts)
        .expect("test workflow must compile")
}

fn contract_validation_make_contract(
    id: u16,
    name: &str,
) -> Result<vb_core::action::ActionContract, Box<dyn std::error::Error>> {
    let action_name = vb_core::action::ActionName::new(name)?;
    Ok(vb_core::action::ActionContract {
        id: ActionId::new(id),
        name: action_name,
        input_slot_count: 1,
        output_slot_count: 1,
        max_input_bytes: 1024,
        max_output_bytes: 1024,
        timeout_ms: 1000,
        idempotency: vb_core::action::Idempotency::DeterministicPure,
        side_effect: vb_core::action::SideEffect::None,
        retry_safety: vb_core::action::RetrySafety::Safe,
        required_capabilities: Box::new([]),
    })
}

#[test]
fn validate_contracts_accepts_valid_do_contract() -> Result<(), Box<dyn std::error::Error>> {
    let shard = contract_validation_test_shard();
    let workflow = contract_validation_do_workflow(0);

    let run = RunId::new(1);
    let caps = CapabilitySet::empty();

    let contract = contract_validation_make_contract(0, "real_action")?;
    let result = shard.validate_submit_admission_with_contracts(
        run,
        &workflow,
        caps,
        &[contract],
    );
    assert!(
        result.is_ok(),
        "valid Do contract must be accepted: {:?}",
        result
    );
    Ok(())
}

