pub(crate) fn validate_submit_admission_with_contracts(
    &self,
    run: RunId,
    workflow: &CompiledWorkflow,
    caps: CapabilitySet,
    action_contracts: &[vb_core::action::ActionContract],
) -> RuntimeResult<()> {
    // Build admission to validate workflow digest
    let digest = workflow.digest();
    self.build_admission(run, digest, caps.clone())?;

    // Validate action contracts: ID matches index, no duplicates, well-formed
    let mut seen_ids = std::collections::HashSet::new();
    for (index, contract) in action_contracts.iter().enumerate() {
        let expected_id = vb_core::ids::ActionId::new(
            u16::try_from(index).map_err(|_| RuntimeError::ContractValidationError {
                action: contract.id,
                error: "contract index exceeds ActionId range".to_string(),
            })?,
        );
        if contract.id != expected_id {
            return Err(RuntimeError::ContractValidationError {
                action: contract.id,
                error: format!(
                    "contract at index {} has ID {} (expected {})",
                    index,
                    contract.id.get(),
                    expected_id.get()
                ),
            });
        }
        if !seen_ids.insert(contract.id) {
            return Err(RuntimeError::ContractValidationError {
                action: contract.id,
                error: "duplicate action ID".to_string(),
            });
        }
        if contract.name.as_str().is_empty() {
            return Err(RuntimeError::ContractValidationError {
